-- Idempotent Gate-0 master-data and source-registry seed.
-- DML only. UUIDs are generated by PostgreSQL; downstream code resolves records by stable codes.

on conflict (issuer_code) do update set
legal_name=excluded.legal_name,short_name=excluded.short_name,jurisdiction=excluded.jurisdiction,
sector=excluded.sector,industry=excluded.industry,reporting_currency=excluded.reporting_currency,
fiscal_year_end_month=excluded.fiscal_year_end_month,fiscal_year_end_day=excluded.fiscal_year_end_day,updated_at=now();

select issuer_id,'600519.SH','XSHG','600519','A','equity','CNY','2001-08-27',true from master.issuers where issuer_code='KWEICHOW_MOUTAI'
on conflict (security_code) do nothing;

on conflict (source_code) do update set
name=excluded.name,source_type=excluded.source_type,homepage_url=excluded.homepage_url,license_name=excluded.license_name,
license_url=excluded.license_url,terms_url=excluded.terms_url,is_free=excluded.is_free,is_open_source=excluded.is_open_source,
pit_capability=excluded.pit_capability,priority=excluded.priority,notes=excluded.notes;
